    public static boolean isConnectionAlive(DBPDataSource dataSource, Connection connection) {
        try {
            if (connection == null || connection.isClosed()) {
                return false;
            }
        } catch (SQLException e) {
            log.debug(e);
            return false;
        }

        // Check for active tasks. Do not run ping if there is active task
        for (DBPDataSourceTask task : dataSource.getContainer().getTasks()) {
            if (task.isActiveTask()) {
                return true;
            }
        }

        // Run ping query
        final String testSQL = dataSource.getSQLDialect().getTestSQL();
        int invalidateTimeout = dataSource.getContainer().getPreferenceStore().getInt(ModelPreferences.CONNECTION_VALIDATION_TIMEOUT);

        // Invalidate in non-blocking task.
        // Timeout is CONNECTION_VALIDATION_TIMEOUT + 2 seconds
        final boolean[] isValid = new boolean[1];
        RuntimeUtils.runTask(monitor -> {

content.content:
469	        RuntimeUtils.runTask(monitor -> {
470	            try {
471	                if (!CommonUtils.isEmpty(testSQL)) {
472	                    // Execute test SQL
473	                    try (Statement dbStat = connection.createStatement()) {
474	                        dbStat.execute(testSQL);
475	                        isValid[0] = true;
476	                    }
477	                } else {
478	                    try {
479	                        isValid[0] = connection.isValid(invalidateTimeout);
480	                    } catch (Throwable e) {
481	                        // isValid may be unsupported by driver
482	                        // Let's try to read table list
483	                        connection.getMetaData().getTables(null, null, "DBEAVERFAKETABLENAMEFORPING", null);
484	                        isValid[0] = true;
485	                    }
486	                }
487	            } catch (SQLException e) {
488	                isValid[0] = false;
489	            }
490	        }, "Ping connection " + dataSource.getContainer().getName(), invalidateTimeout + 2000, true);
491	        return isValid[0];
492	    }
