704	    public static void appendFilterClause(@NotNull StringBuilder sql,
705	                                          @NotNull DBSObjectFilter filter,
706	                                          @NotNull String columnAlias,
707	                                          @NotNull boolean firstClause,
708	                                          DBPDataSource dataSource) {
709	        if (filter.isNotApplicable()) {
710	            return;
711	        }
712	        if (filter.hasSingleMask()) {
713	            if (columnAlias != null) {
714	                firstClause = SQLUtils.appendFirstClause(sql, firstClause);
715	                sql.append(columnAlias);
716	            }
717	            SQLUtils.appendLikeCondition(sql, filter.getSingleMask(), false, dataSource != null ? dataSource.getSQLDialect() : null);
718	            return;
719	        }
720	        List<String> include = filter.getInclude();
721	        if (!CommonUtils.isEmpty(include)) {
722	            if (columnAlias != null) {
723	                firstClause = SQLUtils.appendFirstClause(sql, firstClause);
724	            }
725	            sql.append("(");
726	            for (int i = 0, includeSize = include.size(); i < includeSize; i++) {
727	                if (i > 0)
728	                    sql.append(" OR ");
729	                if (columnAlias != null) {
730	                    sql.append(columnAlias);
731	                }
732	                SQLUtils.appendLikeCondition(sql, include.get(i), false, dataSource != null ? dataSource.getSQLDialect() : null);
733	            }
734	            sql.append(")");
735	        }
736	        List<String> exclude = filter.getExclude();
737	        if (!CommonUtils.isEmpty(exclude)) {
738	            if (columnAlias != null) {
739	                SQLUtils.appendFirstClause(sql, firstClause);
740	            }
741	            sql.append("NOT (");
742	            for (int i = 0, excludeSize = exclude.size(); i < excludeSize; i++) {
743	                if (i > 0)
744	                    sql.append(" OR ");
745	                if (columnAlias != null) {
746	                    sql.append(columnAlias);
747	                }
748	
749	                SQLUtils.appendLikeCondition(sql, exclude.get(i), false, dataSource != null ? dataSource.getSQLDialect() : null);
750	            }
751	            sql.append(")");
752	        }
753	    }
