790	    public static String escapeWildCards(JDBCSession session, String string) {
791	        if (string == null || string.isEmpty() || (string.indexOf('%') == -1 && string.indexOf('_') == -1)) {
792	            return string;
793	        }
794	        try {
795	            SQLDialect dialect = SQLUtils.getDialectFromDataSource(session.getDataSource());
796	            String escapeStr = dialect.getSearchStringEscape();
797	            if (CommonUtils.isEmpty(escapeStr) || escapeStr.equals(" ")) {
798	                return string;
799	            }
800	            return string.replace("%", escapeStr + "%").replace("_", escapeStr + "_");
801	        } catch (Throwable e) {
802	            log.debug("Error escaping wildcard string", e);
803	            return string;
804	        }
805	    }
